package com.aiservice.infrastructure.rabbitmq;import java.util.Map;import org.springframework.amqp.core.*;import org.springframework.amqp.support.converter.JacksonJsonMessageConverter;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;
@Configuration public class RabbitConfiguration{public static final String EXCHANGE="ai.exchange",QUEUE="ai.generation.queue",RETRY="ai.generation.retry.queue",DLQ="ai.generation.dlq";@Bean TopicExchange aiExchange(){return new TopicExchange(EXCHANGE,true,false);}@Bean DirectExchange retryExchange(){return new DirectExchange("ai.retry.exchange",true,false);}@Bean DirectExchange dlx(){return new DirectExchange("ai.dlx",true,false);}@Bean Queue generationQueue(){return QueueBuilder.durable(QUEUE).build();}@Bean Queue retryQueue(@Value("${ai.rabbitmq.retry-delay-ms}")long delay){return QueueBuilder.durable(RETRY).withArguments(Map.of("x-message-ttl",delay,"x-dead-letter-exchange",EXCHANGE,"x-dead-letter-routing-key","ai.generation.requested")).build();}@Bean Queue deadQueue(){return QueueBuilder.durable(DLQ).build();}@Bean Binding mainBinding(Queue generationQueue,TopicExchange aiExchange){return BindingBuilder.bind(generationQueue).to(aiExchange).with("ai.generation.requested");}@Bean Binding retryBinding(Queue retryQueue,DirectExchange retryExchange){return BindingBuilder.bind(retryQueue).to(retryExchange).with(RETRY);}@Bean Binding deadBinding(Queue deadQueue,DirectExchange dlx){return BindingBuilder.bind(deadQueue).to(dlx).with(DLQ);}@Bean JacksonJsonMessageConverter converter(){return new JacksonJsonMessageConverter();}}
